def short861(*args):
    text = ' '.join(str(x) for x in args)
    print(text, file=CONSOLE861, flush=True)
    LOG_FILE861.write(text + '\n')
    LOG_FILE861.flush()


def json_write861(name, value):
    path = ROOT861 / name
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2,
        allow_nan=False), encoding='utf-8')
    return path


def sha256_bytes861(data):
    return hashlib.sha256(data).hexdigest()


def git_blob861(data):
    return hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest()


def load_sources861():
    request = urllib.request.Request(CODELOAD861,
        headers={'User-Agent': 'AKBASCORE-TEST861-GATE0'})
    with urllib.request.urlopen(request, timeout=240) as response:
        archive = response.read(100000001)
    with zipfile.ZipFile(io.BytesIO(archive)) as zipped:
        for name, expected in LOCKS861.items():
            matches = [m for m in zipped.namelist() if m.endswith('/' + name)]
            assert len(matches) == 1, ('SOURCE_MEMBER_NOT_UNIQUE', name, matches)
            data = zipped.read(matches[0])
            actual = git_blob861(data)
            assert actual == expected, ('SOURCE_LOCK_FAILED', name, actual, expected)
            RAW_SOURCES861[name] = data
            if name.endswith('.py'):
                REAL_COMPILE861(data.decode('utf-8'), name, 'exec')
            short861('TABLE A SOURCE', name, actual, 'PASS')
    assert len(RAW_SOURCES861) == 23


