def _selected860_nodes861():
    tree = ast.parse(RAW_SOURCES861['860.py'].decode('utf-8'), filename='860.py')
    names = {'short860', 'short859', 'json_write860', 'json_write859',
        'sha256_bytes860', 'sha256_bytes859', 'git_blob860', 'git_blob859',
        'load_spine860', 'records_digest860', 'margins860', 'relation_roles860',
        'endpoints860', 'resolve_conditions860', 'native_sequences860',
        'decision_quality860', 'quality_dominance860', 'snapshots860',
        'original_condition860', 'score_deltas860'}
    nodes = [copy.deepcopy(n) for n in tree.body if
        isinstance(n, ast.FunctionDef) and n.name in names]
    assert {n.name for n in nodes} == names
    return tree, nodes


def _selected859_nodes861(tree860):
    loader = next(n for n in tree860.body if isinstance(n, ast.FunctionDef)
        and n.name == 'load_spine860')
    assignment = next(n for n in ast.walk(loader) if isinstance(n, ast.Assign)
        and any(isinstance(t, ast.Name) and t.id == 'names' for t in n.targets))
    names = set(ast.literal_eval(assignment.value))
    tree = ast.parse(RAW_SOURCES861['859.py'].decode('utf-8'), filename='859.py')
    nodes = [copy.deepcopy(n) for n in tree.body if
        (isinstance(n, ast.FunctionDef) and n.name in names) or
        (isinstance(n, ast.ClassDef) and n.name in ('Gate1SmokeComplete859', 'Quiet859'))]
    assert {n.name for n in nodes} == names | {'Gate1SmokeComplete859', 'Quiet859'}
    return nodes


def _dependency_audit861(nodes):
    source = ast.unparse(ast.fix_missing_locations(ast.Module(body=nodes, type_ignores=[])))
    table = symtable.symtable(source, 'TEST861_STATIC_GLOBAL_DEPENDENCIES', 'exec')
    required = set()
    def visit(item):
        for symbol in item.get_symbols():
            if symbol.is_referenced() and symbol.is_global():
                required.add(symbol.get_name())
        for child in item.get_children():
            visit(child)
    visit(table)
    available = set(globals()) | set(dir(builtins))
    missing = sorted(required - available)
    assert not missing, ('STATIC_GLOBAL_DEPENDENCIES_MISSING_BEFORE_MODEL', missing)
    STATE861['dependency_audit'] = {'required_globals': sorted(required),
        'missing': missing, 'status': 'PASS_BEFORE_MODEL_LOAD'}
    short861('TABLE A DEPENDENCY AUDIT PASS', len(required), 'globals; missing=0')


def load_spine861():
    assert not STATE861['spine_loaded']
    tree860, nodes860 = _selected860_nodes861()
    nodes859 = _selected859_nodes861(tree860)
    condition_assignment = next(n for n in tree860.body if isinstance(n, ast.Assign)
        and any(isinstance(t, ast.Name) and t.id == 'CONDITION_PLAN860' for t in n.targets))
    globals()['CONDITION_PLAN860'] = ast.literal_eval(condition_assignment.value)
    # First expose TEST860 compatibility helpers and its definition-only 859 loader.
    module860 = ast.fix_missing_locations(ast.Module(body=nodes860, type_ignores=[]))
    exec(REAL_COMPILE861(module860, 'TEST861_REUSED_860_DEFINITIONS_ONLY', 'exec'), globals())
    load_spine860()
    _dependency_audit861(nodes860 + nodes859)
    STATE861['spine_loaded'] = True
    STATE861['spine_ast_sha256'] = sha256_bytes861(ast.dump(ast.Module(
        body=nodes860 + nodes859, type_ignores=[]), include_attributes=False).encode())
    short861('TABLE A SPINE', '860+859 selected definitions only',
        STATE861['spine_ast_sha256'], 'top-level experiment exec=0')


